import { Suspense } from "react";
import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import DeviceFrame from "@/components/DeviceFrame";
import { ProjectMeta } from "@/components/ProjectRow";
import Reveal from "@/components/Reveal";
import { projects } from "@/data/site";

export function generateStaticParams() {
  return projects.map((p) => ({ slug: p.slug }));
}

export async function generateMetadata(
  props: PageProps<"/projects/[slug]">,
): Promise<Metadata> {
  const { slug } = await props.params;
  const project = projects.find((p) => p.slug === slug);
  return project ? { title: project.title, description: project.description } : {};
}

// 读取 params 的部分放在 <Suspense> 里，这样页面跳转能立即显示外壳（Next 16 的 instant navigation 要求）
export default function ProjectPage(props: PageProps<"/projects/[slug]">) {
  return (
    <Suspense fallback={<div className="min-h-screen" />}>
      <ProjectContent params={props.params} />
    </Suspense>
  );
}

async function ProjectContent({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const index = projects.findIndex((p) => p.slug === slug);
  if (index === -1) notFound();

  const project = projects[index];
  const next = projects[(index + 1) % projects.length];

  return (
    <article className="mx-auto max-w-[1180px] px-6 pt-32 sm:px-10">
      <Link href="/#gallery" className="text-xs hover:text-accent">
        ← gallery
      </Link>

      <div className="mt-12 grid items-center gap-12 md:grid-cols-2">
        <Reveal>
          <div className="mx-auto" style={{ width: `min(100%, ${project.device.width * 2}%)` }}>
            <DeviceFrame
              device={project.device}
              screens={[{ src: project.cover.src, alt: project.cover.alt, box: project.device.screen }]}
              sizes="(min-width: 768px) 50vw, 100vw"
              priority
            />
          </div>
        </Reveal>
        <Reveal delay={0.15}>
          <h1 className="font-dot text-4xl sm:text-5xl">{project.title}</h1>
          <div className="mt-6">
            <ProjectMeta project={project} />
          </div>
          <p className="mt-5 max-w-md text-sm leading-relaxed">{project.description}</p>
        </Reveal>
      </div>

      {/* 在这里放作品的视频、过程图等，可以在 site.ts 里给 Project 加字段 */}

      <Link href={`/projects/${next.slug}`} className="group mt-32 block border-t border-line pt-10">
        <p className="text-xs">next</p>
        <p className="font-dot mt-3 text-3xl transition-all group-hover:translate-x-2 group-hover:text-accent">
          {next.title} →
        </p>
      </Link>
    </article>
  );
}
